public class InsufficientManaException extends RuntimeException {
    public InsufficientManaException(int needed, int have) {
        super("Need " + needed + " mana, have " + have);
    }
}

// Throwing it:
if (mana < spellCost) {
    throw new InsufficientManaException(spellCost, mana);
}

try (Scanner sc = new Scanner(System.in)) {
    String input = sc.nextLine();
    System.out.println("You said: " + input);
} // sc.close() called automatically here

